class Solution {
public:
    bool isRectangleCover(vector<vector<int>>& rectangles) {
        long long area = 0;
        set<pair<int, int>> corners;
        int minX = INT_MAX, minY = INT_MAX, maxX = INT_MIN, maxY = INT_MIN;
        for (const auto& r : rectangles) {
            int x1 = r[0], y1 = r[1], x2 = r[2], y2 = r[3];
            area += static_cast<long long>(x2 - x1) * (y2 - y1);
            minX = min(minX, x1);
            minY = min(minY, y1);
            maxX = max(maxX, x2);
            maxY = max(maxY, y2);
            pair<int, int> pts[4] = {{x1, y1}, {x1, y2}, {x2, y1}, {x2, y2}};
            for (const auto& pt : pts) {
                if (corners.count(pt)) corners.erase(pt);
                else corners.insert(pt);
            }
        }
        if (corners.size() != 4) return false;
        if (!corners.count({minX, minY}) || !corners.count({minX, maxY}) ||
            !corners.count({maxX, minY}) || !corners.count({maxX, maxY})) {
            return false;
        }
        return area == static_cast<long long>(maxX - minX) * (maxY - minY);
    }
};

class Solution {
    public boolean isRectangleCover(int[][] rectangles) {
        long area = 0;
        Set<String> corners = new HashSet<>();
        int minX = Integer.MAX_VALUE, minY = Integer.MAX_VALUE;
        int maxX = Integer.MIN_VALUE, maxY = Integer.MIN_VALUE;
        for (int[] r : rectangles) {
            int x1 = r[0], y1 = r[1], x2 = r[2], y2 = r[3];
            area += (long) (x2 - x1) * (y2 - y1);
            minX = Math.min(minX, x1);
            minY = Math.min(minY, y1);
            maxX = Math.max(maxX, x2);
            maxY = Math.max(maxY, y2);
            String[] pts = {
                x1 + "#" + y1, x1 + "#" + y2,
                x2 + "#" + y1, x2 + "#" + y2
            };
            for (String pt : pts) {
                if (!corners.add(pt)) corners.remove(pt);
            }
        }
        if (corners.size() != 4) return false;
        if (!corners.contains(minX + "#" + minY) || !corners.contains(minX + "#" + maxY) ||
            !corners.contains(maxX + "#" + minY) || !corners.contains(maxX + "#" + maxY)) {
            return false;
        }
        return area == (long) (maxX - minX) * (maxY - minY);
    }
}

